protected override async Task ExecuteAsync(CancellationToken ct) {
    await foreach (var msg in _queue.Reader.ReadAllAsync(ct)) {
        using var scope = _scopes.CreateScope();            // scoped service per message
        var svc = scope.ServiceProvider.GetRequiredService<OrderService>();
        var receipt = await svc.PlaceAsync(msg.Order, ct);
        if (receipt is not null) await _out.Writer.WriteAsync(receipt, ct);
    }
}

