processor.ProcessMessageAsync += async args => {
    var order = args.Message.Body.ToObjectFromJson<Order>();
    try {
        var receipt = await _orders.PlaceAsync(order);
        await args.CompleteMessageAsync(args.Message);     // ack after the service
        await _reply.SendAsync(receipt);
    } catch (Exception e) { await args.DeadLetterMessageAsync(args.Message, e.Message); }
};
